import numpy as np

def load(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0]); atoms=[]
    for l in lines[2:2+n]:
        s=l.split(); atoms.append((s[0], np.array([float(s[1]),float(s[2]),float(s[3])])))
    return atoms

for fn in ['complex_opt1.xyz','complex_opt2.xyz']:
    atoms = load(fn)
    ni = atoms[66][1]
    donors = {'N_amine':0, 'N_pzA':4, 'N_pzB':21, 'Cl1':67, 'Cl2':68}
    print(f"--- {fn} ---")
    pos = {}
    for name,i in donors.items():
        d = np.linalg.norm(atoms[i][1]-ni); pos[name]=atoms[i][1]
        print(f"  Ni-{name}: {d:.3f} A")
    # angles around Ni
    names = list(donors.keys())
    for i in range(len(names)):
        for j in range(i+1,len(names)):
            a = pos[names[i]]-ni; b = pos[names[j]]-ni
            ang = np.degrees(np.arccos(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b)))
            print(f"  {names[i]}-Ni-{names[j]}: {ang:.1f} deg")
